# Recursion — a function that calls itself

# Classic: factorial
# n! = n * (n-1) * (n-2) * ... * 1

def factorial(n):
    # Base case: stop condition
    if n <= 1:
        return 1
    # Recursive case: call itself with smaller input
    else:
        return n * factorial(n - 1)

print("5! =", factorial(5))  # 5 * 4 * 3 * 2 * 1 = 120
print("3! =", factorial(3))  # 3 * 2 * 1 = 6

print("\n")

# Counting down with recursion
def countdown(n):
    if n <= 0:
        print("Blast off!")
    else:
        print(n)
        countdown(n - 1)  # Call itself with n-1

countdown(5)

print("\n")

# Summing a list with recursion
def sum_list(numbers):
    # Base case: empty list
    if not numbers:
        return 0
    # Recursive case: first + sum of rest
    else:
        return numbers[0] + sum_list(numbers[1:])

nums = [1, 2, 3, 4, 5]
print(f"Sum of {nums}: {sum_list(nums)}")

print("\n")

# Recursion vs loop
def factorial_loop(n):
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

print(f"Factorial loop: {factorial_loop(5)}")

